# 횟수를 세도 함수 결과는 그대로여야 한다
counts = {}

def counted(func):
    def wrapper(*args, **kwargs):
        name = func.__name__
        counts[name] = counts.get(name, 0) + 1
        func(*args, **kwargs)
    return wrapper

@counted
def total(prices):
    return sum(prices)

print(total([1000, 2500]), counts)

